import SynQt

Edge {
    id: feed

    loaded: false

    function load() {
        if (!Caller.hasScope("user")) {
            Caller.emitDenied(qsTr("Please sign in."));
            return;
        }
        Store.allows(Caller.identity.sub).then(ok => {
            if (!ok) {
                Caller.emitDenied(qsTr("Not allowed."));
                return;
            }
            Recent.items().then(rows => {
                feed.setRows(rows);
                feed.loaded = true;
            });
        });
    }
}

